 * Checks if a number is prime by testing divisibility
 * @param {number} number - The number to test for primality
 * @returns {boolean} - True if the number is prime, false otherwise
 */
export default function trialDivision(number) {
  // Handle edge cases
  if (number <= 1) {
    return false; // Numbers <= 1 are not prime
  }

  if (number === 2) {
    return true; // 2 is the only even prime number
  }

  if (number % 2 === 0) {
    return false; // All other even numbers are not prime
  }

  // Trial division: check odd divisors up to sqrt(number)
  // If a number has a divisor greater than its square root,
  // it must also have a divisor smaller than its square root
  const squareRoot = Math.sqrt(number);

  for (let divisor = 3; divisor <= squareRoot; divisor += 2) {
    if (number % divisor === 0) {
      return false; // Found a divisor, so not prime
    }
  }

  return true; // No divisors found, number is prime
}

